CREATE TYPE "StreamSessionStatus" AS ENUM ('PENDING','CONNECTING','STREAMING','PAUSED','COMPLETED','CANCELLED','FAILED','TIMED_OUT','DISCONNECTED');
CREATE TABLE "stream_sessions" ("id" UUID NOT NULL,"workspace_id" UUID NOT NULL,"created_by" UUID NOT NULL,"conversation_id" UUID,"provider_id" UUID NOT NULL,"model_id" UUID NOT NULL,"agent_runtime_id" UUID,"execution_request_id" UUID,"execution_run_id" UUID,"request_hash" TEXT NOT NULL,"status" "StreamSessionStatus" NOT NULL DEFAULT 'PENDING',"state_version" INTEGER NOT NULL DEFAULT 0,"reconnect_count" INTEGER NOT NULL DEFAULT 0,"retry_count" INTEGER NOT NULL DEFAULT 0,"timeout_ms" INTEGER NOT NULL,"started_at" TIMESTAMP(3),"finished_at" TIMESTAMP(3),"cancelled_at" TIMESTAMP(3),"disconnected_at" TIMESTAMP(3),"provider_metadata" JSONB NOT NULL DEFAULT '{}',"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL,CONSTRAINT "stream_sessions_pkey" PRIMARY KEY ("id"));
CREATE TABLE "stream_chunks" ("id" UUID NOT NULL,"session_id" UUID NOT NULL,"sequence" INTEGER NOT NULL,"content" TEXT NOT NULL DEFAULT '',"role" TEXT,"delta" BOOLEAN NOT NULL DEFAULT true,"finish_reason" TEXT,"provider_metadata" JSONB NOT NULL DEFAULT '{}',"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "stream_chunks_pkey" PRIMARY KEY ("id"));
CREATE TABLE "stream_diagnostics" ("id" UUID NOT NULL,"session_id" UUID NOT NULL,"code" TEXT NOT NULL,"message" TEXT NOT NULL,"metadata" JSONB NOT NULL DEFAULT '{}',"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "stream_diagnostics_pkey" PRIMARY KEY ("id"));
CREATE TABLE "stream_metrics" ("id" UUID NOT NULL,"session_id" UUID NOT NULL,"time_to_first_byte_ms" INTEGER,"total_duration_ms" INTEGER,"chunk_count" INTEGER NOT NULL DEFAULT 0,"characters" INTEGER NOT NULL DEFAULT 0,"estimated_tokens" INTEGER NOT NULL DEFAULT 0,"cancellation_count" INTEGER NOT NULL DEFAULT 0,"reconnect_count" INTEGER NOT NULL DEFAULT 0,"updated_at" TIMESTAMP(3) NOT NULL,CONSTRAINT "stream_metrics_pkey" PRIMARY KEY ("id"));
CREATE TABLE "stream_snapshots" ("id" UUID NOT NULL,"session_id" UUID NOT NULL,"revision" INTEGER NOT NULL,"snapshot" JSONB NOT NULL,"snapshot_hash" TEXT NOT NULL,"checksum" TEXT NOT NULL,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "stream_snapshots_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "stream_chunks_session_sequence_key" ON "stream_chunks"("session_id","sequence"); CREATE UNIQUE INDEX "stream_metrics_session_id_key" ON "stream_metrics"("session_id"); CREATE UNIQUE INDEX "stream_snapshots_session_revision_key" ON "stream_snapshots"("session_id","revision"); CREATE INDEX "stream_sessions_workspace_status_idx" ON "stream_sessions"("workspace_id","status","created_at"); CREATE INDEX "stream_sessions_workspace_request_hash_idx" ON "stream_sessions"("workspace_id","request_hash"); CREATE INDEX "stream_chunks_session_created_idx" ON "stream_chunks"("session_id","created_at"); CREATE INDEX "stream_diagnostics_session_created_idx" ON "stream_diagnostics"("session_id","created_at"); CREATE INDEX "stream_snapshots_session_created_idx" ON "stream_snapshots"("session_id","created_at");
ALTER TABLE "stream_sessions" ADD CONSTRAINT "stream_sessions_workspace_id_fkey" FOREIGN KEY ("workspace_id") REFERENCES "workspaces"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "stream_chunks" ADD CONSTRAINT "stream_chunks_session_id_fkey" FOREIGN KEY ("session_id") REFERENCES "stream_sessions"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "stream_diagnostics" ADD CONSTRAINT "stream_diagnostics_session_id_fkey" FOREIGN KEY ("session_id") REFERENCES "stream_sessions"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "stream_metrics" ADD CONSTRAINT "stream_metrics_session_id_fkey" FOREIGN KEY ("session_id") REFERENCES "stream_sessions"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "stream_snapshots" ADD CONSTRAINT "stream_snapshots_session_id_fkey" FOREIGN KEY ("session_id") REFERENCES "stream_sessions"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
